"use client"

import { createColumnHelper } from "@tanstack/react-table"
import { EllipsisIcon, ListChecksIcon, PencilIcon } from "lucide-react"

import { Button } from "@/components/ui/button"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import {
  DataTableColumnHeader,
  type DataTableFeatures,
} from "@/components/blocks/openlmis/data-table/data-table"
import { useMenuOpensDialog } from "@/components/blocks/openlmis/data-table/row-actions"
import type { ResponsiveColumn } from "@/components/blocks/openlmis/data-table/responsive-columns"
import { roleTypeOf } from "@/components/blocks/openlmis/role-assignments/role-assignments"
import { roleTypeInfo } from "@/components/openlmis/roles-page/role-form"

import type { ListedRole } from "@/components/openlmis/roles-page/mock-roles"

/** The columns the View menu lists, in order; the role's name is left out, so it always shows. */
export const HIDEABLE_COLUMNS: (ResponsiveColumn & { label: string })[] = [
  { id: "type", label: "Role Type", hideBelow: "md" },
  { id: "description", label: "Description", hideBelow: "4xl" },
  { id: "count", label: "Number Of Users", hideBelow: "xl" },
]

const columnHelper = createColumnHelper<DataTableFeatures, ListedRole>()

/** Each is left out when the user may not do it, and the menu goes when both are. */
export type RoleRowActions = {
  onEdit?: ((roleId: string) => void) | undefined
  onViewRights?: ((roleId: string) => void) | undefined
}

export function createRoleColumns(actions: RoleRowActions) {
  const hasActions = Boolean(actions.onEdit || actions.onViewRights)
  return columnHelper.columns([
    columnHelper.accessor("name", {
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title="Role" />
      ),
      cell: ({ getValue }) => <span className="font-medium">{getValue()}</span>,
      meta: { className: "@xl/table:w-1/3 @4xl/table:w-1/4" },
    }),
    columnHelper.accessor((role) => roleTypeOf(role), {
      id: "type",
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title="Role Type" />
      ),
      cell: ({ getValue }) => {
        const type = getValue()
        return type ? (
          roleTypeInfo(type).label
        ) : (
          <span className="text-muted-foreground">No Type</span>
        )
      },
      meta: { className: "@xl/table:w-40" },
    }),
    columnHelper.accessor("description", {
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title="Description" />
      ),
      cell: ({ getValue }) =>
        getValue() || <span className="text-muted-foreground">-</span>,
      enableSorting: false,
    }),
    columnHelper.accessor("count", {
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title="Number Of Users" />
      ),
      cell: ({ getValue }) => (
        <span className="tabular-nums">{getValue()}</span>
      ),
      meta: { className: "w-36" },
    }),
    ...(hasActions
      ? [
          columnHelper.display({
            id: "actions",
            header: () => <span className="sr-only">Actions</span>,
            cell: ({ row }) => (
              <RoleActions actions={actions} role={row.original} />
            ),
            meta: { className: "w-16" },
          }),
        ]
      : []),
  ])
}

function RoleActions({
  role,
  actions: { onEdit, onViewRights },
}: {
  role: ListedRole
  actions: RoleRowActions
}) {
  const menu = useMenuOpensDialog()

  return (
    <div className="flex justify-end">
      <DropdownMenu onOpenChange={menu.onOpenChange}>
        <DropdownMenuTrigger
          render={
            <Button
              aria-label={`Actions for ${role.name}`}
              size="icon-sm"
              variant="ghost"
            />
          }
        >
          <EllipsisIcon />
        </DropdownMenuTrigger>
        <DropdownMenuContent
          align="end"
          className="w-auto"
          finalFocus={menu.finalFocus}
        >
          {onEdit && (
            <DropdownMenuItem onClick={menu.opensDialog(() => onEdit(role.id))}>
              <PencilIcon />
              Edit
            </DropdownMenuItem>
          )}
          {onViewRights && (
            <DropdownMenuItem
              onClick={menu.opensDialog(() => onViewRights(role.id))}
            >
              <ListChecksIcon />
              View Rights
            </DropdownMenuItem>
          )}
        </DropdownMenuContent>
      </DropdownMenu>
    </div>
  )
}

"use client"

import { revalidateLogic } from "@tanstack/react-form"
import { type ReactNode, useId, useMemo, useState } from "react"

import {
  AlertDialog,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog"
import { Button } from "@/components/ui/button"
import {
  Field,
  FieldDescription,
  FieldGroup,
  FieldTitle,
} from "@/components/ui/field"
import { Skeleton } from "@/components/ui/skeleton"
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs"
import {
  type Right,
  type RightType,
  type Role,
  rightLabel,
  roleTypeOf,
} from "@/components/blocks/openlmis/role-assignments/role-assignments"
import { Callout } from "@/components/openlmis/callout"
import {
  FormDialog,
  FormDialogBody,
  FormDialogCancel,
  FormDialogDescription,
  FormDialogError,
  FormDialogFooter,
  FormDialogForm,
  FormDialogHeader,
  FormDialogSubmit,
  FormDialogTitle,
} from "@/components/openlmis/form-dialog/form-dialog"
import { useDialogTarget } from "@/components/openlmis/form-dialog/use-dialog-target"
import { useAppForm } from "@/components/openlmis/form-fields/form"
import {
  FieldLabelText,
  FieldSkeleton,
  SkeletonLine,
} from "@/components/openlmis/form-fields/form-fields"

import {
  asksBeforeSaving,
  EMPTY_ROLE_FORM,
  otherTypeRights,
  ROLE_TYPES,
  type RoleFormResult,
  type RoleFormValues,
  roleFormSchema,
  roleTypeInfo,
  toRoleFormValues,
  toRoleResult,
} from "@/components/openlmis/roles-page/role-form"

/** `new` to create a role, or the id of the role to edit. */
export type RoleFormDialogTarget = "new" | (string & {})

type RoleFormDialogProps = {
  /** Opens the dialog while set. */
  target: RoleFormDialogTarget | undefined
  /** The role being edited; a skeleton shows until it is set. */
  role?: Role | undefined
  /** Every role, so a name already taken is refused. */
  roles: readonly Pick<Role, "id" | "name">[]
  /** Every right of every type; the rights field shows a skeleton until it is set. */
  rights: readonly Right[] | undefined
  /** How many users hold the role; saving a role in use asks first. */
  holders?: number
  /** Without it, the dialog says creating and editing roles needs rights the user lacks. */
  canEdit?: boolean
  /** The role to edit no longer exists. */
  notFound?: boolean
  /** Called with the trimmed values; save them, then clear `target` to close. */
  onSubmit: (result: RoleFormResult, role: Role | undefined) => void
  /** Keeps the dialog open and shows a spinner while the role is saved. */
  pending?: boolean
  /** Shown above the fields, e.g. why the save failed. */
  error?: ReactNode
  /** Names a right from its code; defaults to the code in words, e.g. "Requisition Approve". */
  formatRight?: (name: string) => string
  onClose: () => void
}

export function RoleFormDialog({
  target,
  role,
  roles,
  rights,
  holders = 0,
  canEdit = true,
  notFound = false,
  onSubmit,
  pending = false,
  error,
  formatRight = rightLabel,
  onClose,
}: RoleFormDialogProps) {
  const { shown, dialogProps } = useDialogTarget(target, onClose)
  const isNew = shown === "new"
  const title = isNew ? "Create Role" : "Edit Role"

  return (
    <FormDialog {...dialogProps(pending)}>
      {shown &&
        (!canEdit ? (
          <MessageContent
            message="Creating and editing roles needs Manage User Roles and View Rights. Ask an administrator if you need them."
            title={title}
          />
        ) : notFound && !isNew ? (
          <MessageContent message="This role no longer exists." title={title} />
        ) : !isNew && role === undefined ? (
          <RoleFormSkeleton submitLabel="Save Changes" title={title} />
        ) : (
          <RoleForm
            error={error}
            formatRight={formatRight}
            holders={holders}
            // Keyed, so opening another role starts a fresh form.
            key={role?.id ?? "new"}
            onSubmit={onSubmit}
            pending={pending}
            rights={rights}
            role={isNew ? undefined : role}
            roles={roles}
          />
        ))}
    </FormDialog>
  )
}

type RoleFormProps = Pick<
  RoleFormDialogProps,
  "roles" | "rights" | "onSubmit" | "error"
> & {
  role: Role | undefined
  holders: number
  pending: boolean
  formatRight: (name: string) => string
}

function RoleForm({
  role,
  roles,
  rights,
  holders,
  onSubmit,
  pending,
  error,
  formatRight,
}: RoleFormProps) {
  const schema = useMemo(
    () => roleFormSchema(roles, role?.id),
    [roles, role?.id]
  )
  const [confirming, setConfirming] = useState<RoleFormValues>()
  // The type of a saved role is fixed, since its holders' assignments are shaped for it.
  const typeLocked = roleTypeOf(role) !== undefined
  const dropped = otherTypeRights(role)
  const submit = (values: RoleFormValues) =>
    onSubmit(toRoleResult(values, rights ?? []), role)

  const form = useAppForm({
    defaultValues: role ? toRoleFormValues(role) : EMPTY_ROLE_FORM,
    // Quiet until the first submit, then each field re-checks as it is corrected.
    validationLogic: revalidateLogic({
      mode: "submit",
      modeAfterSubmission: "change",
    }),
    validators: { onDynamic: schema },
    onSubmit: ({ value }) =>
      asksBeforeSaving(role, holders) ? setConfirming(value) : submit(value),
  })

  return (
    <FormDialogForm onSubmit={form.handleSubmit}>
      <FormDialogHeader>
        <FormDialogTitle>{role ? "Edit Role" : "Create Role"}</FormDialogTitle>
        <FormDialogDescription>
          {role
            ? `Details for ${role.name}.`
            : "Pick a type, then name the role and choose its rights."}
        </FormDialogDescription>
      </FormDialogHeader>
      <FormDialogBody>
        {/* Rights belong to one type, so changing it starts the choice of rights over. */}
        <form.AppField
          listeners={{ onChange: () => form.setFieldValue("rights", []) }}
          name="type"
        >
          {(field) => (
            <RoleTypeTabs
              locked={typeLocked}
              onChange={field.handleChange}
              type={field.state.value}
            >
              <FieldGroup>
                {error && (
                  <FormDialogError
                    description={error}
                    title="Could Not Save Role"
                  />
                )}
                {dropped.length > 0 && (
                  <Callout title="Rights Of Another Type" tone="warning">
                    {otherTypeMessage(
                      dropped.map((right) => formatRight(right.name))
                    )}
                  </Callout>
                )}
                <form.AppField name="name">
                  {(name) => (
                    <name.TextField autoComplete="off" label="Name" required />
                  )}
                </form.AppField>
                <form.AppField name="description">
                  {(description) => (
                    <description.TextareaField label="Description" required />
                  )}
                </form.AppField>
                {rights === undefined ? (
                  <FieldSkeleton label="Rights" required />
                ) : (
                  <form.AppField name="rights">
                    {(rightsField) => {
                      const items = rightItems(
                        rights,
                        field.state.value,
                        formatRight
                      )
                      const selected = items.filter((item) =>
                        rightsField.state.value.includes(item.value)
                      ).length
                      return (
                        <rightsField.MultiComboboxField
                          description={`${selected} of ${items.length} selected.`}
                          emptyMessage="No rights found."
                          items={items}
                          label="Rights"
                          placeholder="Search Rights..."
                          removeLabel={(label) => `Remove ${label}`}
                          required
                        />
                      )
                    }}
                  </form.AppField>
                )}
              </FieldGroup>
            </RoleTypeTabs>
          )}
        </form.AppField>
      </FormDialogBody>
      <FormDialogFooter>
        <FormDialogCancel disabled={pending} />
        <FormDialogSubmit disabled={rights === undefined} pending={pending}>
          {role ? "Save Changes" : "Create Role"}
        </FormDialogSubmit>
      </FormDialogFooter>
      <AlertDialog
        onOpenChange={(open) => !open && setConfirming(undefined)}
        open={Boolean(confirming)}
      >
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Change A Role In Use?</AlertDialogTitle>
            <AlertDialogDescription>
              {holders === 1 ? "1 user has" : `${holders} users have`}{" "}
              {role?.name}. Saving changes what they can do right away.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <Button
              onClick={() => {
                if (confirming) submit(confirming)
                setConfirming(undefined)
              }}
            >
              Save Changes
            </Button>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </FormDialogForm>
  )
}

function rightItems(
  rights: readonly Right[],
  type: RightType,
  formatRight: (name: string) => string
) {
  return (
    rights
      .filter((right) => right.type === type)
      .map((right) => ({ value: right.name, label: formatRight(right.name) }))
      // oxlint-disable-next-line unicorn/no-array-sort -- sorts the fresh mapped array
      .sort((a, b) => a.label.localeCompare(b.label))
  )
}

function otherTypeMessage(labels: string[]) {
  const list = labels.join(", ")
  return labels.length === 1
    ? `This role also holds a right of another type, ${list}. Saving removes it, since a role holds rights of one type.`
    : `This role also holds ${labels.length} rights of another type: ${list}. Saving removes them, since a role holds rights of one type.`
}

type RoleTypeTabsProps = {
  type: RightType
  locked: boolean
  onChange: (type: RightType) => void
  children: ReactNode
}

function RoleTypeTabs({ type, locked, onChange, children }: RoleTypeTabsProps) {
  const id = useId()

  return (
    <Tabs
      className="gap-4"
      onValueChange={(value) => onChange(value as RightType)}
      value={type}
    >
      <Field className="gap-2">
        <FieldTitle id={`${id}-label`}>
          <FieldLabelText label="Role Type" required />
        </FieldTitle>
        {/* Its own container, so the four tabs go two by two when the dialog is narrow. */}
        <div className="@container">
          <TabsList
            aria-describedby={`${id}-description`}
            aria-labelledby={`${id}-label`}
            className="grid w-full grid-cols-2 group-data-horizontal/tabs:h-auto @md:flex @md:group-data-horizontal/tabs:h-8"
          >
            {ROLE_TYPES.map((item) => (
              <TabsTrigger
                disabled={locked && item.type !== type}
                key={item.type}
                value={item.type}
              >
                {item.label}
              </TabsTrigger>
            ))}
          </TabsList>
        </div>
        <FieldDescription id={`${id}-description`}>
          {roleTypeInfo(type).description}
        </FieldDescription>
      </Field>
      {/* Not a tab stop of its own: the fields inside it take focus. */}
      <TabsContent tabIndex={-1} value={type}>
        {children}
      </TabsContent>
    </Tabs>
  )
}

function MessageContent({
  title,
  message,
}: {
  title: string
  message: string
}) {
  return (
    <>
      <FormDialogHeader>
        <FormDialogTitle>{title}</FormDialogTitle>
        <FormDialogDescription>{message}</FormDialogDescription>
      </FormDialogHeader>
      <FormDialogFooter>
        <FormDialogCancel>Close</FormDialogCancel>
      </FormDialogFooter>
    </>
  )
}

/** Laid out like the form, so nothing moves when the role arrives. */
export function RoleFormSkeleton({
  title,
  submitLabel,
}: {
  title: string
  submitLabel: string
}) {
  return (
    <>
      <FormDialogHeader>
        <FormDialogTitle>{title}</FormDialogTitle>
        <SkeletonLine />
      </FormDialogHeader>
      <FormDialogBody>
        <div aria-busy className="flex flex-col gap-4">
          <Field className="gap-2">
            <FieldTitle>
              <FieldLabelText label="Role Type" required />
            </FieldTitle>
            <div className="@container">
              <Skeleton className="h-15 w-full @md:h-8" />
            </div>
            <SkeletonLine />
          </Field>
          <FieldGroup>
            <FieldSkeleton label="Name" required />
            <FieldSkeleton label="Description" required />
            <FieldSkeleton label="Rights" required />
          </FieldGroup>
        </div>
      </FormDialogBody>
      <FormDialogFooter>
        <FormDialogCancel />
        <FormDialogSubmit disabled>{submitLabel}</FormDialogSubmit>
      </FormDialogFooter>
    </>
  )
}

import { z } from "zod"

import {
  type Right,
  type RightType,
  type Role,
  roleTypeOf,
} from "@/components/blocks/openlmis/role-assignments/role-assignments"

/** The four role types, in the order OpenLMIS shows them, with what each one is for. */
export const ROLE_TYPES = [
  {
    type: "SUPERVISION",
    label: "Supervision",
    description:
      "Rights for managing requisitions, stock and cold chain equipment at supervised facilities.",
  },
  {
    type: "ORDER_FULFILLMENT",
    label: "Fulfillment",
    description:
      "Rights for viewing, transferring and editing orders and shipments at a warehouse.",
  },
  {
    type: "REPORTS",
    label: "Reports",
    description: "Rights for viewing reports and editing their templates.",
  },
  {
    type: "GENERAL_ADMIN",
    label: "Administration",
    description:
      "Rights for managing the system: users, facilities, products, programs and other settings.",
  },
] as const satisfies readonly {
  type: RightType
  label: string
  description: string
}[]

export type RoleTypeInfo = (typeof ROLE_TYPES)[number]

export function roleTypeInfo(type: RightType): RoleTypeInfo {
  return ROLE_TYPES.find((item) => item.type === type) ?? ROLE_TYPES[0]
}

const sameName = (a: string, b: string) =>
  a.trim().toLowerCase() === b.trim().toLowerCase()

/** Role names are unique ignoring case; the role being edited keeps its own. */
export function roleFormSchema(
  roles: readonly Pick<Role, "id" | "name">[],
  editingId?: string
) {
  return z.object({
    type: z.custom<RightType>(),
    name: z
      .string()
      .trim()
      .min(1, "Enter a name.")
      .refine(
        (name) =>
          !roles.some(
            (role) => role.id !== editingId && sameName(role.name, name)
          ),
        "Another role already has this name."
      ),
    description: z.string().trim().min(1, "Enter a description."),
    /** The chosen rights by name, which is unique in OpenLMIS. */
    rights: z.array(z.string()).min(1, "Choose at least one right."),
  })
}

export type RoleFormValues = z.input<ReturnType<typeof roleFormSchema>>

export const EMPTY_ROLE_FORM: RoleFormValues = {
  type: ROLE_TYPES[0].type,
  name: "",
  description: "",
  rights: [],
}

/** Only the rights of the role's type: the form lists no others, and a role holds one type. */
export function toRoleFormValues(role: Role): RoleFormValues {
  // A role saved without rights has no type yet, so it starts on the first one.
  const type = roleTypeOf(role) ?? ROLE_TYPES[0].type
  return {
    type,
    name: role.name,
    description: role.description ?? "",
    rights: role.rights
      .filter((right) => right.type === type)
      .map((right) => right.name),
  }
}

/** Rights of another type than the role's, which a save through this form drops. */
export function otherTypeRights(role: Role | undefined): Right[] {
  const type = roleTypeOf(role)
  return role?.rights.filter((right) => right.type !== type) ?? []
}

/** Changing a role changes what everyone who holds it can do, so that is asked first. */
export function asksBeforeSaving(role: Role | undefined, holders: number) {
  return role !== undefined && holders > 0
}

/** What the form saves: trimmed text and the chosen rights of the role's type. */
export type RoleFormResult = {
  name: string
  description: string
  rights: Right[]
}

export function toRoleResult(
  values: RoleFormValues,
  rights: readonly Right[]
): RoleFormResult {
  const chosen = new Set(values.rights)
  return {
    name: values.name.trim(),
    description: values.description.trim(),
    rights: rights
      .filter((right) => right.type === values.type && chosen.has(right.name))
      .map(({ name, type }) => ({ name, type })),
  }
}

"use client"

import { CheckIcon } from "lucide-react"

import { Button } from "@/components/ui/button"
import {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"
import {
  type Role,
  rightLabel,
} from "@/components/blocks/openlmis/role-assignments/role-assignments"
import { useDialogTarget } from "@/components/openlmis/form-dialog/use-dialog-target"

type RoleRightsDialogProps = {
  /** The role whose rights are shown; open while set. Keep its identity while it stays open. */
  role: Role | undefined
  onClose: () => void
  /** Names a right from its code; defaults to the code in words, e.g. "Requisition Approve". */
  formatRight?: (name: string) => string
}

/** What a role lets its holder do, which the old UI only showed on hover. */
export function RoleRightsDialog({
  role,
  onClose,
  formatRight = rightLabel,
}: RoleRightsDialogProps) {
  const { shown, dialogProps } = useDialogTarget(role, onClose)
  const labels = (shown?.rights ?? []).map((right) => formatRight(right.name))
  // oxlint-disable-next-line unicorn/no-array-sort -- sorts the fresh mapped array
  const rights = labels.sort()

  return (
    <Dialog {...dialogProps()}>
      {/* Flex instead of grid, so a long list scrolls inside the dialog. */}
      {/* oxlint-disable-next-line shadcn/no-arbitrary-values -- no scale value keeps a margin inside the dynamic viewport */}
      <DialogContent className="flex max-h-[calc(100dvh-2rem)] flex-col">
        <DialogHeader className="gap-1 pe-8">
          <DialogTitle>{shown ? `${shown.name} Rights` : "Rights"}</DialogTitle>
          <DialogDescription>
            {shown?.description ||
              `${rights.length === 1 ? "1 right" : `${rights.length} rights`} granted by this role.`}
          </DialogDescription>
        </DialogHeader>
        {rights.length > 0 && (
          <ul className="-mx-4 flex min-h-0 flex-col gap-2 overflow-y-auto px-4 text-sm">
            {rights.map((right) => (
              <li className="flex items-center gap-2" key={right}>
                <CheckIcon
                  aria-hidden="true"
                  className="size-4 shrink-0 text-success"
                />
                {right}
              </li>
            ))}
          </ul>
        )}
        <DialogFooter>
          <DialogClose render={<Button type="button" variant="outline" />}>
            Close
          </DialogClose>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

import {
  type RightType,
  type Role,
  roleTypeOf,
} from "@/components/blocks/openlmis/role-assignments/role-assignments"
import { ROLE_TYPES } from "@/components/openlmis/roles-page/role-form"

import type { ListedRole } from "@/components/openlmis/roles-page/mock-roles"

export const ROLE_SORT_FIELDS = ["name", "type", "count"] as const

export type RoleSortField = (typeof ROLE_SORT_FIELDS)[number]

export type RolesQuery = {
  search: string
  /** An empty string means every type. */
  type: RightType | ""
  sortBy: RoleSortField
  sortDesc: boolean
  pageIndex: number
  pageSize: number
}

// Folds case and accents, so "sante" finds "Santé".
const fold = (text: string) =>
  text.normalize("NFD").replace(/\p{M}/gu, "").toLowerCase()

export function filterRoles(
  roles: readonly ListedRole[],
  { search, type }: Pick<RolesQuery, "search" | "type">
) {
  const term = fold(search.trim())
  return roles.filter(
    (role) =>
      (!type || roleTypeOf(role) === type) &&
      (!term ||
        [role.name, role.description ?? ""].some((text) =>
          fold(text).includes(term)
        ))
  )
}

const byName = (a: Role, b: Role) =>
  a.name.localeCompare(b.name, undefined, { sensitivity: "base" })

// A role with no rights has no type, so it sorts after the four.
const typeRank = (role: Role) => {
  const index = ROLE_TYPES.findIndex((item) => item.type === roleTypeOf(role))
  return index === -1 ? ROLE_TYPES.length : index
}

const COMPARE: Record<RoleSortField, (a: ListedRole, b: ListedRole) => number> =
  {
    name: byName,
    type: (a, b) => typeRank(a) - typeRank(b),
    count: (a, b) => a.count - b.count,
  }

export function sortRoles(
  roles: readonly ListedRole[],
  field: RoleSortField,
  desc: boolean
) {
  const compare = COMPARE[field]
  // oxlint-disable-next-line unicorn/no-array-sort -- sorts a fresh copy; toSorted needs the ES2023 lib
  return [...roles].sort(
    (a, b) => (desc ? -compare(a, b) : compare(a, b)) || byName(a, b)
  )
}

"use client"

import {
  type ColumnVisibilityState,
  functionalUpdate,
  useTable,
} from "@tanstack/react-table"
import { PlusIcon, SearchXIcon, ShieldIcon } from "lucide-react"
import { useCallback, useMemo, useState } from "react"

import { Button } from "@/components/ui/button"
import {
  DataTable,
  DataTableEmpty,
  DataTablePagination,
  dataTableFeatures,
} from "@/components/blocks/openlmis/data-table/data-table"
import {
  useColumnVisibility,
  useContainerSize,
} from "@/components/blocks/openlmis/data-table/responsive-columns"
import {
  ListToolbar,
  ListToolbarEnd,
  ListToolbarFilter,
  ListToolbarSearch,
} from "@/components/blocks/openlmis/list-toolbar"
import type { RightType } from "@/components/blocks/openlmis/role-assignments/role-assignments"
import {
  RoleFormDialog,
  type RoleFormDialogTarget,
} from "@/components/openlmis/roles-page/role-form-dialog"
import type { RoleFormResult } from "@/components/openlmis/roles-page/role-form"
import { ROLE_TYPES } from "@/components/openlmis/roles-page/role-form"
import { RoleRightsDialog } from "@/components/openlmis/roles-page/role-rights-dialog"
import {
  Workspace,
  WorkspaceContent,
  WorkspaceDescription,
  WorkspaceHeader,
  WorkspaceHeading,
  WorkspaceIcon,
  WorkspaceTitle,
} from "@/components/blocks/openlmis/workspace"
import { Callout } from "@/components/openlmis/callout"
import { ColumnViewOptions } from "@/components/openlmis/column-view-options"
import { PageBreadcrumbs } from "@/components/openlmis/page-breadcrumbs"
import { SearchInput } from "@/components/openlmis/search-input/search-input"
import { SelectFilter } from "@/components/openlmis/select-filter"

import { type ListedRole, MOCK_RIGHTS, MOCK_ROLES } from "@/components/openlmis/roles-page/mock-roles"
import { createRoleColumns, HIDEABLE_COLUMNS } from "@/components/openlmis/roles-page/role-columns"
import {
  filterRoles,
  type RoleSortField,
  type RolesQuery,
  sortRoles,
} from "@/components/openlmis/roles-page/roles-list"

const INITIAL_QUERY: RolesQuery = {
  search: "",
  type: "",
  sortBy: "name",
  sortDesc: false,
  pageIndex: 0,
  pageSize: 10,
}

const getRowId = (role: ListedRole) => role.id

type OpenDialog =
  | { kind: "role"; target: RoleFormDialogTarget }
  | { kind: "rights"; roleId: string }

type Notice = { title: string; description: string }

type RolesPageProps = {
  /** Whether the user may create and edit roles; without it the list is read only. */
  canEdit?: boolean
  /** Whether the user may see what each role grants. */
  canViewRights?: boolean
}

/** The roles list screen; mount it from any route, e.g. the `page.tsx` this template ships. */
export function RolesPage({
  canEdit = true,
  canViewRights = true,
}: RolesPageProps) {
  const [roles, setRoles] = useState(MOCK_ROLES)
  const [query, setQuery] = useState(INITIAL_QUERY)
  const [dialog, setDialog] = useState<OpenDialog>()
  const [notice, setNotice] = useState<Notice>()
  const closeDialog = () => setDialog(undefined)
  /** A filter or sort starts again from the first page; paging keeps the rest. */
  const update = (patch: Partial<RolesQuery>) => {
    setNotice(undefined)
    setQuery((previous) => ({
      ...previous,
      ...patch,
      pageIndex: "pageIndex" in patch ? (patch.pageIndex ?? 0) : 0,
    }))
  }

  // Stable, so the columns built from them keep their identity between renders.
  const onEdit = useCallback((roleId: string) => {
    setNotice(undefined)
    setDialog({ kind: "role", target: roleId })
  }, [])
  const onViewRights = useCallback((roleId: string) => {
    setNotice(undefined)
    setDialog({ kind: "rights", roleId })
  }, [])
  const columns = useMemo(
    () =>
      createRoleColumns({
        onEdit: canEdit ? onEdit : undefined,
        onViewRights: canViewRights ? onViewRights : undefined,
      }),
    [canEdit, canViewRights, onEdit, onViewRights]
  )
  const [measureContent, contentSize] = useContainerSize<HTMLDivElement>()
  // Kept for the visit only; store it (e.g. in localStorage) to remember it across visits.
  const columnChoices = useState<ColumnVisibilityState>({})
  const columnView = useColumnVisibility(
    HIDEABLE_COLUMNS,
    columnChoices,
    contentSize
  )

  // Every role is in memory, so filtering, sorting and paging happen here.
  const matching = useMemo(
    () => sortRoles(filterRoles(roles, query), query.sortBy, query.sortDesc),
    [roles, query]
  )
  // A filter that leaves fewer pages is held to the last page that exists.
  const lastPage = Math.max(0, Math.ceil(matching.length / query.pageSize) - 1)
  const pagination = useMemo(
    () => ({
      pageIndex: Math.min(query.pageIndex, lastPage),
      pageSize: query.pageSize,
    }),
    [query.pageIndex, query.pageSize, lastPage]
  )
  const data = useMemo(
    () =>
      matching.slice(
        pagination.pageIndex * pagination.pageSize,
        (pagination.pageIndex + 1) * pagination.pageSize
      ),
    [matching, pagination]
  )
  // Memoized: the table compares controlled state by reference and would reset it every render.
  const sorting = useMemo(
    () => [{ id: query.sortBy, desc: query.sortDesc }],
    [query.sortBy, query.sortDesc]
  )

  const table = useTable({
    features: dataTableFeatures,
    columns,
    data,
    getRowId,
    rowCount: matching.length,
    manualPagination: true,
    manualSorting: true,
    enableSortingRemoval: false,
    state: { pagination, sorting, columnVisibility: columnView.visibility },
    onPaginationChange: (updater) =>
      update(functionalUpdate(updater, pagination)),
    onSortingChange: (updater) => {
      const [next] = functionalUpdate(updater, sorting)
      if (next)
        update({ sortBy: next.id as RoleSortField, sortDesc: next.desc })
    },
  })

  const roleTarget = dialog?.kind === "role" ? dialog.target : undefined
  const editing = roles.find((role) => role.id === roleTarget)
  const rightsRole =
    dialog?.kind === "rights"
      ? roles.find((role) => role.id === dialog.roleId)
      : undefined
  const isFiltered = Boolean(query.search || query.type)

  const saveRole = (
    result: RoleFormResult,
    existing: ListedRole | undefined
  ) => {
    if (existing) {
      setRoles((current) =>
        current.map((role) =>
          role.id === existing.id ? { ...role, ...result } : role
        )
      )
      setNotice({
        title: "Role Updated",
        description:
          existing.count === 0
            ? `Changes to ${result.name} are saved.`
            : `Changes to ${result.name} are saved and apply to ${existing.count === 1 ? "1 user" : `${existing.count} users`}.`,
      })
    } else {
      setRoles((current) => [
        ...current,
        { id: `role-${current.length + 1}`, ...result, count: 0 },
      ])
      setNotice({
        title: "Role Created",
        description: `${result.name} is ready to give to users.`,
      })
    }
    closeDialog()
  }

  return (
    <Workspace>
      <PageBreadcrumbs
        items={[
          { label: "Home", href: "#" },
          { label: "Administration" },
          { label: "Roles" },
        ]}
      />
      <WorkspaceHeader>
        <WorkspaceHeading>
          <WorkspaceIcon>
            <ShieldIcon />
          </WorkspaceIcon>
          <WorkspaceTitle>Roles</WorkspaceTitle>
          <WorkspaceDescription>
            Named sets of rights to give to users.
          </WorkspaceDescription>
        </WorkspaceHeading>
      </WorkspaceHeader>
      <WorkspaceContent>
        {/* Measured, because the room for columns depends on a sidebar as well as the window. */}
        <div className="flex flex-col gap-4" ref={measureContent}>
          {notice && (
            <Callout title={notice.title} tone="success">
              {notice.description}
            </Callout>
          )}
          <ListToolbar>
            <ListToolbarSearch>
              <SearchInput
                label="Search by name or description"
                onValueChange={(search) => update({ search })}
                value={query.search}
              />
            </ListToolbarSearch>
            <ListToolbarFilter>
              <SelectFilter
                label="Role Type"
                onValueChange={(type) =>
                  update({ type: type as RightType | "" })
                }
                options={ROLE_TYPES.map((item) => ({
                  value: item.type,
                  label: item.label,
                }))}
                value={query.type}
              />
            </ListToolbarFilter>
            <ListToolbarEnd>
              <ColumnViewOptions
                columns={HIDEABLE_COLUMNS}
                onReset={columnView.onReset}
                onVisibilityChange={columnView.onVisibilityChange}
                visibility={columnView.visibility}
              />
            </ListToolbarEnd>
            {canEdit && (
              <div className="w-full @2xl/main:w-auto">
                <Button
                  className="w-full"
                  onClick={() => {
                    setNotice(undefined)
                    setDialog({ kind: "role", target: "new" })
                  }}
                >
                  <PlusIcon data-icon="inline-start" />
                  Create Role
                </Button>
              </div>
            )}
          </ListToolbar>

          <DataTable
            empty={
              isFiltered ? (
                <DataTableEmpty
                  action={
                    <Button
                      onClick={() => update({ search: "", type: "" })}
                      variant="destructive"
                    >
                      Clear Filters
                    </Button>
                  }
                  description="No role matches these filters."
                  icon={<SearchXIcon />}
                  title="No Matching Roles"
                />
              ) : (
                <DataTableEmpty
                  description="Roles you create appear here."
                  icon={<ShieldIcon />}
                  title="No Roles Yet"
                />
              )
            }
            footer={
              matching.length > 0 && <DataTablePagination table={table} />
            }
            table={table}
          />
        </div>
      </WorkspaceContent>

      <RoleFormDialog
        canEdit={canEdit}
        holders={editing?.count ?? 0}
        onClose={closeDialog}
        onSubmit={(result) => saveRole(result, editing)}
        rights={MOCK_RIGHTS}
        role={editing}
        roles={roles}
        target={roleTarget}
      />
      <RoleRightsDialog onClose={closeDialog} role={rightsRole} />
    </Workspace>
  )
}

import { RolesPage } from "@/components/openlmis/roles-page/roles-page"

// A Next.js App Router route; in any other React app, render RolesPage from your own route.
export default function Page() {
  return <RolesPage />
}
